import {test,expect,type Page} from '@playwright/test'
import {build} from 'esbuild'
import {readFile} from 'node:fs/promises'
test.describe.configure({retries:0,timeout:25000})
const origin='http://127.0.0.1:4265',prefix='/__competitions/'
let javascript='',stylesheet=''
test.beforeAll(async()=>{const bundled=await build({entryPoints:['tests/fixtures/mobile-competitions.ts'],bundle:true,platform:'browser',format:'esm',outfile:'competitions.js',write:false,jsx:'automatic',loader:{'.module.css':'local-css'}});javascript=bundled.outputFiles.find(f=>f.path.endsWith('.js'))!.text;stylesheet=(await Promise.all(['style.css','website-ui.css','app.css','website-parity.css','app-atmosphere.css'].map(f=>readFile('mobile/bundled/'+f,'utf8')))).join('\n')})
test.beforeEach(async({page})=>{await page.route('**/*',async route=>{const url=new URL(route.request().url());if(url.origin!==origin||!url.pathname.startsWith(prefix))return route.abort();if(url.pathname.endsWith('app.js'))return route.fulfill({contentType:'text/javascript',body:javascript});if(url.pathname.endsWith('style.css'))return route.fulfill({contentType:'text/css',body:stylesheet});if(url.pathname!==prefix)return route.fulfill({status:404,body:''});return route.fulfill({contentType:'text/html',body:'<!doctype html><html lang="en"><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="./style.css"></head><body data-screen="lab"><header class="app-header"><span>TenAceIQ</span></header><main id="app"></main><script type="module" src="./app.js"></script></body></html>'})})})
const state=(page:Page)=>page.evaluate(()=>(window as unknown as {competitionFixture:{state:{calls:number}}}).competitionFixture.state.calls)
async function open(page:Page,mode='team'){await page.goto(origin+prefix+'?view='+mode);await page.getByRole('button',{name:'Your competitions'}).click();await expect(page.getByRole('dialog')).toContainText('Awaiting approval')}
async function bounded(page:Page){expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);const widths=await page.getByRole('dialog').evaluate(el=>({client:el.clientWidth,scroll:el.scrollWidth,overflow:[...el.querySelectorAll('*')].filter(c=>c.getBoundingClientRect().right>el.getBoundingClientRect().right).slice(0,8).map(c=>({tag:c.tagName,cls:c.className,text:c.textContent?.slice(0,40),width:c.getBoundingClientRect().width}))}));if(widths.scroll>widths.client)await page.screenshot({path:test.info().outputPath('competitions-overflow.png')});expect(widths.scroll<=widths.client,JSON.stringify(widths)).toBe(true)}
async function change(page:Page,values:Record<string,unknown>){await page.evaluate(v=>Object.assign((window as unknown as {competitionFixture:{state:Record<string,unknown>}}).competitionFixture.state,v),values)}
for(const width of [320,390]){
 test('league schedule, results, approved roster and shared standings at '+width+'px',async({page},info)=>{
  await page.setViewportSize({width,height:844});await open(page);await bounded(page);await page.screenshot({path:info.outputPath('competitions-home.png')})
  await page.getByRole('button',{name:/^Open league/}).click();await expect(page.getByRole('heading',{name:'Coming up'})).toBeVisible();const calls=await state(page)
  await page.getByRole('button',{name:'Schedule',exact:true}).click();await expect(page.getByRole('dialog')).toContainText('Cancelled');await bounded(page)
  await page.getByRole('button',{name:'Results',exact:true}).click();await expect(page.getByRole('dialog')).toContainText('6-4, 6-3')
  await page.getByRole('button',{name:'Standings',exact:true}).click();await expect(page.getByRole('dialog')).toContainText('14 points');await bounded(page);await page.screenshot({path:info.outputPath('competitions-standings.png')})
  await page.getByRole('button',{name:'Teams',exact:true}).click();await expect(page.getByRole('dialog')).toContainText('Approved entries');expect(await state(page)).toBe(calls)
  await page.getByRole('button',{name:'← Competitions',exact:true}).click();await page.getByRole('button',{name:'Browse leagues',exact:true}).click();await page.getByLabel('Find a TiQ league').fill('nothing');const before=await state(page);expect(await state(page)).toBe(before);await page.getByRole('button',{name:'Search',exact:true}).click();await expect(page.getByRole('dialog')).toContainText('No public leagues found')
  await page.getByRole('button',{name:'Close',exact:true}).click();await expect(page.getByRole('dialog')).toHaveCount(0);await expect(page.getByRole('button',{name:'Your competitions'})).toBeFocused()
 })
 test('long names and larger text stay within the sheet at '+width+'px',async({page},info)=>{await page.setViewportSize({width,height:844});await open(page,'long');await page.addStyleTag({content:':root{font-size:22px!important}'});await bounded(page);await page.getByRole('button',{name:/^Open league/}).click();await expect(page.getByRole('heading',{name:'Coming up'})).toBeVisible();await bounded(page);await page.getByRole('button',{name:'Schedule',exact:true}).click();await bounded(page);await page.screenshot({path:info.outputPath('competitions-large-text.png')})})
 test('a failed refresh clears stale data and a manual retry recovers at '+width+'px',async({page})=>{await page.setViewportSize({width,height:844});await open(page);await change(page,{offline:true});await page.getByRole('button',{name:'Refresh',exact:true}).click();await expect(page.getByRole('alert')).toContainText('Couldn’t load');await expect(page.locator('.competition-card')).toHaveCount(0);await change(page,{offline:false});await page.getByRole('button',{name:'Refresh',exact:true}).click();await expect(page.locator('.competition-card')).toHaveCount(1);await bounded(page)})
 test('incomplete results withhold standings at '+width+'px',async({page})=>{await page.setViewportSize({width,height:844});await open(page,'incomplete');await page.getByRole('button',{name:/^Open league/}).click();await page.getByRole('button',{name:'Standings',exact:true}).click();await expect(page.getByRole('dialog')).toContainText('Standings are withheld');await expect(page.getByRole('dialog')).not.toContainText('14 points');await bounded(page)})
 test('individual results never show a team standings control at '+width+'px',async({page})=>{await page.setViewportSize({width,height:844});await open(page,'individual');await page.getByRole('button',{name:/^Open league/}).click();await expect(page.getByRole('button',{name:'Standings',exact:true})).toHaveCount(0);await page.getByRole('button',{name:'Results',exact:true}).click();await expect(page.getByRole('dialog')).toContainText('6-4, 6-3');await bounded(page)})
 test('closing and account changes reject late responses at '+width+'px',async({page})=>{await page.setViewportSize({width,height:844});await open(page);await change(page,{delay:true});await page.getByRole('button',{name:'Refresh',exact:true}).click();await page.getByRole('button',{name:'Close',exact:true}).click();await page.evaluate(()=>(window as unknown as {competitionFixture:{state:{release:()=>void}}}).competitionFixture.state.release());await expect(page.getByRole('dialog')).toHaveCount(0);await change(page,{delay:false});await page.getByRole('button',{name:'Your competitions'}).click();await expect(page.locator('.competition-card')).toHaveCount(1);await change(page,{delay:true});await page.getByRole('button',{name:'Refresh',exact:true}).click();await change(page,{owner:'different-owner'});await page.evaluate(()=>(window as unknown as {competitionFixture:{state:{release:()=>void}}}).competitionFixture.state.release());await expect(page.getByRole('alert')).toContainText('Couldn’t load');await expect(page.locator('.competition-card')).toHaveCount(0)})
}

for(const width of [320,390]){
 test('review, attest and save one pending league request at '+width+'px',async({page},info)=>{
  await page.setViewportSize({width,height:844});await open(page);await page.getByRole('button',{name:/^Open league/}).click();await page.getByRole('button',{name:'Entry & registration'}).click()
  const entry=page.getByRole('dialog',{name:'League entry',exact:true});await expect(entry.getByRole('heading',{name:'Join the season'})).toBeVisible();await expect(entry.getByRole('button',{name:'Request entry',exact:true})).toBeDisabled();await entry.getByRole('checkbox',{name:/40 & Over/}).check();await expect(entry.getByRole('button',{name:'Request entry',exact:true})).toBeEnabled();await page.addStyleTag({content:':root{font-size:22px!important}'});expect(await entry.evaluate(el=>el.scrollWidth<=el.clientWidth)).toBe(true);await page.screenshot({path:info.outputPath('league-entry-review.png')});await entry.getByRole('button',{name:'Request entry',exact:true}).click();await expect(entry).toContainText('Request saved.');await expect(entry).toContainText('Awaiting organizer approval');await expect(entry.getByRole('button',{name:'Request entry',exact:true})).toHaveCount(0);await entry.getByRole('button',{name:'Check entry status'}).click();await expect(entry).toContainText('Awaiting organizer approval');expect(await page.evaluate(()=>(window as unknown as {competitionFixture:{state:{entryPosts:number}}}).competitionFixture.state.entryPosts)).toBe(1);await entry.getByRole('button',{name:'← League',exact:true}).click();await expect(entry).toHaveCount(0);await expect(page.getByRole('heading',{name:'Coming up'})).toBeVisible()
 })
 test('lost entry reply locks resubmission until the saved status is checked at '+width+'px',async({page})=>{await page.setViewportSize({width,height:844});await open(page);await change(page,{entryLostReply:true});await page.getByRole('button',{name:/^Open league/}).click();await page.getByRole('button',{name:'Entry & registration'}).click();const entry=page.getByRole('dialog',{name:'League entry',exact:true});await entry.getByRole('checkbox',{name:/40 & Over/}).check();await entry.getByRole('button',{name:'Request entry',exact:true}).click();await expect(entry).toContainText('could not be confirmed');await expect(entry.getByRole('button',{name:'Request entry',exact:true})).toBeDisabled();await entry.getByRole('button',{name:'Check entry status'}).click();await expect(entry).toContainText('Awaiting organizer approval');await expect(entry.getByRole('button',{name:'Request entry',exact:true})).toHaveCount(0)})
 test('team entitlement, closed registration and narrow long-name entry at '+width+'px',async({page})=>{await page.setViewportSize({width,height:844});await open(page,'entry-team');await change(page,{entryAllowed:false});await page.getByRole('button',{name:/^Open league/}).click();await page.getByRole('button',{name:'Entry & registration'}).click();const entry=page.getByRole('dialog',{name:'League entry',exact:true});await expect(entry).toContainText('requires active League access');await expect(entry.getByRole('button',{name:'Request entry',exact:true})).toHaveCount(0);await change(page,{entryAllowed:true});await entry.getByRole('button',{name:'Check entry status'}).click();await entry.getByLabel('Team name', {exact:true}).fill('North Aces');await expect(entry.getByRole('button',{name:'Request entry',exact:true})).toBeEnabled();await change(page,{entryClosed:true});await entry.getByRole('button',{name:'Check entry status'}).click();await expect(entry).toContainText('Registration is closed');await expect(entry.getByRole('button',{name:'Request entry',exact:true})).toHaveCount(0)})
 test('entry close and account change reject late confirmations at '+width+'px',async({page})=>{await page.setViewportSize({width,height:844});await open(page);await page.getByRole('button',{name:/^Open league/}).click();await change(page,{delay:true});await page.getByRole('button',{name:'Entry & registration'}).click();const entry=page.getByRole('dialog',{name:'League entry',exact:true});await entry.getByRole('button',{name:'← League',exact:true}).click();await change(page,{delay:false});await page.evaluate(()=>(window as unknown as {competitionFixture:{state:{release:()=>void}}}).competitionFixture.state.release());await expect(entry).toHaveCount(0);await expect(page.getByRole('heading',{name:'Coming up'})).toBeVisible();await page.getByRole('button',{name:'Entry & registration'}).click();await entry.getByRole('checkbox',{name:/40 & Over/}).check();await change(page,{delay:true});await entry.getByRole('button',{name:'Request entry',exact:true}).click();await change(page,{owner:'different-owner'});await page.evaluate(()=>(window as unknown as {competitionFixture:{state:{release:()=>void}}}).competitionFixture.state.release());await expect(entry).not.toContainText('Request saved.');await expect(entry.getByRole('alert')).toBeVisible()})
}

test('long linked-player identity remains readable in enlarged text at 320px',async({page},info)=>{await page.setViewportSize({width:320,height:844});await open(page,'entry-long');await page.getByRole('button',{name:/^Open league/}).click();await page.getByRole('button',{name:'Entry & registration'}).click();const entry=page.getByRole('dialog',{name:'League entry',exact:true});await expect(entry.getByRole('heading',{name:'Join the season'})).toBeVisible();await page.addStyleTag({content:':root{font-size:22px!important}'});expect(await entry.evaluate(el=>el.scrollWidth<=el.clientWidth)).toBe(true);await entry.getByRole('checkbox',{name:/40 & Over/}).check();await expect(entry.getByRole('button',{name:'Request entry',exact:true})).toBeEnabled();await page.screenshot({path:info.outputPath('league-entry-long-name.png')})})

test('changed requirements reset attestations while an unchanged status refresh preserves the draft',async({page})=>{await page.setViewportSize({width:320,height:844});await open(page);await page.getByRole('button',{name:/^Open league/}).click();await page.getByRole('button',{name:'Entry & registration'}).click();const entry=page.getByRole('dialog',{name:'League entry',exact:true});await entry.getByRole('checkbox',{name:/40 & Over/}).check();await entry.getByRole('button',{name:'Check entry status'}).click();await expect(entry.getByRole('checkbox',{name:/40 & Over/})).toBeChecked();await change(page,{entryChanged:true});await entry.getByRole('button',{name:'Check entry status'}).click();await expect(entry.getByRole('alert')).toContainText('details changed');await expect(entry.getByRole('checkbox',{name:/55 & Over/})).not.toBeChecked();await expect(entry.getByRole('button',{name:'Request entry',exact:true})).toBeDisabled();await entry.getByRole('checkbox',{name:/55 & Over/}).check();await expect(entry.getByRole('button',{name:'Request entry',exact:true})).toBeEnabled()})

async function openRequests(page:Page,mode='office'){await page.goto(origin+prefix+'?view='+mode);await page.getByRole('button',{name:'Open League Office',exact:true}).click();await page.getByRole('button',{name:/Northside 4.0/}).click();await page.getByRole('button',{name:'Review entry requests'}).click();const dialog=page.getByRole('dialog',{name:'Entry requests',exact:true});await expect(dialog.getByRole('heading',{name:'Entry requests',exact:true})).toBeVisible();return dialog}
for(const width of [320,390]){
 test('organizer confirms self-attested evidence and sees a saved approval at '+width+'px',async({page},info)=>{await page.setViewportSize({width,height:844});const dialog=await openRequests(page);await dialog.getByRole('button',{name:'Review Alex Server',exact:true}).click();await expect(dialog).toContainText('40 & Over · self');await expect(dialog.getByRole('button',{name:'Approve entry',exact:true})).toBeDisabled();await dialog.getByRole('checkbox').check();await expect(dialog.getByRole('button',{name:'Approve entry',exact:true})).toBeDisabled();await dialog.getByLabel('Review note / question').fill('Age eligibility confirmed with player.');await expect(dialog.getByRole('button',{name:'Approve entry',exact:true})).toBeEnabled();await page.addStyleTag({content:':root{font-size:22px!important}'});expect(await dialog.evaluate(e=>e.scrollWidth<=e.clientWidth)).toBe(true);await page.screenshot({path:info.outputPath('competitions-organizer-review.png')});await dialog.getByRole('button',{name:'Approve entry',exact:true}).click();await expect(dialog).toContainText('Decision saved.');await expect(dialog).toContainText('Approved');await dialog.getByRole('button',{name:'Refresh requests'}).click();await expect(dialog).toContainText('No pending requests.');expect(await page.evaluate(()=>(window as unknown as {competitionFixture:{state:{decisionPosts:number}}}).competitionFixture.state.decisionPosts)).toBe(1);await dialog.getByRole('button',{name:'← League Office',exact:true}).click();await expect(page.getByRole('dialog',{name:'League Office',exact:true})).toContainText('Northside 4.0')})
 test('organizer asks for missing evidence and must wait for the player at '+width+'px',async({page})=>{await page.setViewportSize({width,height:844});const dialog=await openRequests(page);await dialog.getByRole('button',{name:'Review Alex Server',exact:true}).click();await dialog.getByLabel('Review note / question').fill('Please confirm your age division.');await dialog.getByRole('button',{name:'Ask for information',exact:true}).click();await expect(dialog).toContainText('Information requested');await dialog.getByRole('button',{name:'Refresh requests'}).click();await dialog.getByRole('button',{name:'Review Alex Server',exact:true}).click();await expect(dialog).toContainText('Waiting for the player');await dialog.getByRole('checkbox').check();await dialog.getByLabel('Review note / question').fill('Checked');await expect(dialog.getByRole('button',{name:'Approve entry',exact:true})).toBeDisabled();await expect(dialog.getByRole('button',{name:'Decline entry',exact:true})).toBeEnabled()})
 test('lost organizer reply locks a second decision until cloud refresh at '+width+'px',async({page})=>{await page.setViewportSize({width,height:844});const dialog=await openRequests(page);await dialog.getByRole('button',{name:'Review Alex Server',exact:true}).click();await change(page,{decisionLostReply:true});await dialog.getByRole('button',{name:'Decline entry',exact:true}).click();await expect(dialog).toContainText('could not be confirmed');await expect(dialog.getByRole('button',{name:'Decline entry',exact:true})).toBeDisabled();await dialog.getByRole('button',{name:'Refresh requests'}).click();await expect(dialog).toContainText('No pending requests.');expect(await page.evaluate(()=>(window as unknown as {competitionFixture:{state:{decisionPosts:number}}}).competitionFixture.state.decisionPosts)).toBe(1)})
 test('player replies to an information request with fresh attestations at '+width+'px',async({page})=>{await page.setViewportSize({width,height:844});await open(page,'entry-information');await page.getByRole('button',{name:/^Open league/}).click();await page.getByRole('button',{name:'Entry & registration'}).click();const dialog=page.getByRole('dialog',{name:'League entry',exact:true});await expect(dialog).toContainText('Please confirm your age division.');await expect(dialog.getByRole('button',{name:'Send eligibility reply'})).toBeDisabled();await dialog.getByRole('checkbox',{name:/40 & Over/}).check();await dialog.getByRole('button',{name:'Send eligibility reply'}).click();await expect(dialog).toContainText('Reply saved.');expect(await page.evaluate(()=>(window as unknown as {competitionFixture:{state:{entryPosts:number}}}).competitionFixture.state.entryPosts)).toBe(1)})
}
test('organizer stale review, closed seasons and verified mismatches do not approve',async({page})=>{let dialog=await openRequests(page);await dialog.getByRole('button',{name:'Review Alex Server',exact:true}).click();await change(page,{decisionConflict:true});await dialog.getByRole('button',{name:'Decline entry',exact:true}).click();await expect(dialog).toContainText('This entry changed');await expect(dialog.getByRole('button',{name:'Decline entry',exact:true})).toBeDisabled();dialog=await openRequests(page,'office-ineligible');await dialog.getByRole('button',{name:'Review Alex Server',exact:true}).click();await dialog.getByRole('checkbox').check();await dialog.getByLabel('Review note (optional)').fill('Review');await expect(dialog.getByRole('button',{name:'Approve entry',exact:true})).toBeDisabled();dialog=await openRequests(page,'office-closed');await dialog.getByRole('button',{name:'Review Alex Server',exact:true}).click();await expect(dialog).toContainText('closed for entry decisions');await expect(dialog.getByRole('button',{name:'Decline entry',exact:true})).toBeDisabled()})
test('organizer long names, team review and late confirmation stay bounded and account bound',async({page},info)=>{await page.setViewportSize({width:320,height:844});let dialog=await openRequests(page,'office-long');await dialog.getByRole('button',{name:/^Review Alex/}).click();await page.addStyleTag({content:':root{font-size:22px!important}'});expect(await dialog.evaluate(e=>e.scrollWidth<=e.clientWidth)).toBe(true);await page.screenshot({path:info.outputPath('competitions-organizer-long-name.png')});dialog=await openRequests(page,'office-team');await dialog.getByRole('button',{name:'Review North Aces',exact:true}).click();await expect(dialog.getByRole('button',{name:'Ask for information',exact:true})).toHaveCount(0);await dialog.getByRole('checkbox').check();await dialog.getByLabel('Review note / question').fill('Team and division confirmed.');await change(page,{delay:true});await dialog.getByRole('button',{name:'Approve entry',exact:true}).click();await change(page,{owner:'other-owner'});await page.evaluate(()=>(window as unknown as {competitionFixture:{state:{release:()=>void}}}).competitionFixture.state.release());await expect(dialog).not.toContainText('Decision saved.');await expect(dialog.getByRole('alert')).toBeVisible()})

test('a revised organizer question clears old attestations even when the league digest is unchanged',async({page})=>{await open(page,'entry-information');await page.getByRole('button',{name:/^Open league/}).click();await page.getByRole('button',{name:'Entry & registration'}).click();const dialog=page.getByRole('dialog',{name:'League entry',exact:true});await dialog.getByRole('checkbox',{name:/40 & Over/}).check();await change(page,{entryQuestionChanged:true});await dialog.getByRole('button',{name:'Check entry status'}).click();await expect(dialog).toContainText('Please reconfirm your rating and age division.');await expect(dialog.getByRole('checkbox',{name:/40 & Over/})).not.toBeChecked();await expect(dialog.getByRole('button',{name:'Send eligibility reply'})).toBeDisabled()})


