async function insideSheet(locator:ReturnType<Page['locator']>){return locator.evaluate(el=>{const host=el.closest('dialog')!,frame=host.getBoundingClientRect(),rect=el.getBoundingClientRect();return rect.top>=frame.top+host.clientTop&&rect.bottom<=frame.top+host.clientTop+host.clientHeight})}
